files.content:
html {
  block-size: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  background: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
  block-size: 100%;
}

.wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: hidden;
  background-color: #fff5ee;
  background-image:
    linear-gradient(transparent 60%, rgb(220 20 60/0.6) 60%),
    linear-gradient(90deg, transparent 60%, rgb(220 20 60/0.6) 60%);
  background-position: center 1em;
  background-size: 2em 2em;
  inline-size: 100%;
  max-inline-size: 850px;
  block-size: 400px;
}

.plate {
  position: relative;
  display: inline-block;
  margin: 0 10px;
  border-radius: 130px;
  border-bottom: solid 5px #ddd;
  box-shadow: 0 8px 0 rgb(0 0 0 / 0.1);
  background: white;
  inline-size: 260px;
  block-size: 260px;
}

.pizza {
  position: absolute;
  z-index: 1;
  overflow: hidden;
  transform: rotate(320deg);
  transform-origin: 50% 100%;
  inline-size: 400px;
  block-size: 200px;
}

.pizza::before {
  content: '';
  display: block;
  border-radius: 200px 200px 0 0;
  background-color: #fbdb65; /* рисуем кусок пиццы */
  background-image:
    radial-gradient(
      circle at 50% 100%,
      transparent,
      transparent 60%,
      #ffb500 60%,
      #ffb500 62%,
      #ff9204 62%,
      #ff9204 100%
    ),
    radial-gradient(
      circle at 50% 50%,
      #cc2e36 16px,
      #ffb500 16px,
      #ffb500 20px,
      transparent 20px
    ),
    radial-gradient(
      circle at 5px 3px,
      transparent 6px,
      #fdeaa8 6px,
      #fdeaa8 10px,
      transparent 10px
    );
  background-position: 100% 100%, 26% 22%, 22% 32%;
  background-size: 100% 100%, 60px 60px, 60px 60px;
  transform: rotate(90deg); /* обрезаем четвертинку пиццы */
  transform-origin: 50% 100%;
  inline-size: 400px;
  block-size: 200px;
}
